begin;
do $$
declare owner_id uuid; volunteer uuid; qa_device uuid:=gen_random_uuid(); qa_event uuid:=gen_random_uuid(); other_event uuid:=gen_random_uuid(); trip uuid:=gen_random_uuid(); code_no bigint; gid text; op jsonb; r jsonb; reg jsonb; refused boolean; stock_op uuid:=gen_random_uuid(); conflict_op uuid:=gen_random_uuid();
begin
 select id into owner_id from wellness_members where role='admin' order by id limit 1;select id into volunteer from wellness_members where role='volunteer' order by id limit 1;
 insert into wellness_missions(id,name,code) values(trip,'QA rollback mission','QA-'||upper(trip::text));
 insert into wellness_events(id,mission_id,name,starts,ends,location) values(qa_event,trip,'QA day A',current_date,current_date,'Location A'),(other_event,trip,'QA day B',current_date,current_date,'Location B');
 update wellness_members set status='pending' where id=volunteer;
 if wellness_join(volunteer,'QA-'||upper(trip::text))<>trip then raise exception 'join failed';end if;
 if not exists(select 1 from wellness_members where id=volunteer and status='active') then raise exception 'join not active';end if;
 if exists(select 1 from wellness_assignments where user_id=volunteer and event_id=qa_event) then raise exception 'per-user assignments unexpectedly needed';end if;
 insert into wellness_devices(id,user_id,prefix,label) values(qa_device,volunteer,'QA','Rollback test') returning code into code_no;
 gid:='QA-'||lpad(code_no::text,4,'0')||'-000001-X';
 op:=jsonb_build_object('id',gen_random_uuid(),'event_id',qa_event,'device_id',qa_device,'guest_id',gid,'station','measurements','data',jsonb_build_object('height','170','weight','68','waist','82'),'base_revision',null,'captured_at',now(),'date_ack',true);
 r:=wellness_apply(volunteer,op);if r->>'status'<>'saved' then raise exception 'measurement failed';end if;
 if exists(select 1 from wellness_records where event_id=qa_event and station='registration') then raise exception 'registration unexpectedly required';end if;
 if wellness_apply(volunteer,op)<>r then raise exception 'retry not idempotent';end if;
 if (select count(*) from wellness_records where event_id=qa_event)<>1 then raise exception 'retry duplicated';end if;
 if wellness_apply(volunteer,jsonb_set(op,'{id}',to_jsonb(conflict_op))) ->>'status'<>'conflict' then raise exception 'duplicate overwrote';end if;
 refused:=false;begin perform wellness_approve(owner_id,qa_event,true);exception when others then refused:=true;end;if not refused then raise exception 'unresolved day approved';end if;
 update wellness_receipts set result='{"status":"reviewed"}' where id=conflict_op;
 reg:=jsonb_set(jsonb_set(jsonb_set(op,'{id}',to_jsonb(gen_random_uuid())),'{station}','"registration"'),'{data}',jsonb_build_object('name','QA fictional','consent','yes'));
 perform wellness_apply(volunteer,reg);
 if (select count(*) from wellness_records where event_id=qa_event and guest_id=gid)<>2 then raise exception 'out-of-order join failed';end if;
 perform wellness_apply(volunteer,jsonb_set(jsonb_set(op,'{id}',to_jsonb(gen_random_uuid())),'{event_id}',to_jsonb(other_event)));
 if (select count(*) from wellness_records where guest_id=gid)<>3 then raise exception 'locations mixed';end if;
 perform wellness_stock_add(owner_id,stock_op,qa_event,'1.25',10,'Test received');perform wellness_stock_add(owner_id,stock_op,qa_event,'1.25',10,'Test received');
 perform wellness_stock_add(owner_id,gen_random_uuid(),qa_event,'1.25',-2,'Test adjustment');
 if (select received from wellness_stock where event_id=qa_event and grade='1.25')<>8 then raise exception 'stock retry or negative adjustment failed';end if;
 perform wellness_apply(volunteer,jsonb_set(jsonb_set(jsonb_set(op,'{id}',to_jsonb(gen_random_uuid())),'{station}','"glasses"'),'{data}',jsonb_build_object('grade','1.25','quantity','1','status','Provided')));
 perform wellness_apply(volunteer,jsonb_set(jsonb_set(jsonb_set(op,'{id}',to_jsonb(gen_random_uuid())),'{station}','"consultation"'),'{data}',jsonb_build_object('reason','Fictional consultation')));
 perform wellness_approve(owner_id,qa_event,true);
 if not exists(select 1 from wellness_events where id=qa_event and approval='approved') then raise exception 'approval failed';end if;
 refused:=false;begin perform wellness_apply(volunteer,jsonb_set(op,'{id}',to_jsonb(gen_random_uuid())));exception when others then refused:=true;end;if not refused then raise exception 'approved day accepted new record';end if;
 perform wellness_approve(owner_id,qa_event,false);
 update wellness_members set status='disabled' where id=volunteer;
 refused:=false;begin perform wellness_apply(volunteer,op);exception when others then refused:=true;end;if not refused then raise exception 'disabled user accepted';end if;
 update wellness_members set status='active' where id=volunteer;
 delete from wellness_mission_members where mission_id=trip and user_id=volunteer;
 refused:=false;begin perform wellness_apply(volunteer,jsonb_set(op,'{id}',to_jsonb(gen_random_uuid())));exception when others then refused:=true;end;if not refused then raise exception 'unjoined mission accepted';end if;
 if has_table_privilege('anon','public.wellness_records','select') or has_table_privilege('authenticated','public.wellness_records','select') or has_function_privilege('authenticated','public.wellness_apply(uuid,jsonb)','execute') then raise exception 'browser bypass allowed';end if;
end $$;
select 'PASS: mission-code join, all stations without assignment, out-of-order records, idempotency, conflicts, location separation, stock receipt retry and negative correction, daily approval/reopen, frozen approved data, disabled/unjoined rejection, browser isolation' as result;
rollback;
